// Generated by AI
using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Stores absorbed waste in one compartment per type (automatic classification)
/// and lets the player choose which compartment to empty into a bin.
/// Put this on the player root.
/// </summary>
public class BackpackInventory : MonoBehaviour
{
    [SerializeField] private int capacityPerType = 10;

    private readonly Dictionary<WasteType, int> storedWaste = new Dictionary<WasteType, int>();
    private int typeCount;

    public WasteType SelectedType { get; private set; } = WasteType.Plastic;

    // The HUD can subscribe to these events to update itself.
    public event Action<WasteType, int> OnWasteChanged;
    public event Action<WasteType> OnSelectionChanged;

    private void Awake()
    {
        typeCount = Enum.GetValues(typeof(WasteType)).Length;
        foreach (WasteType type in Enum.GetValues(typeof(WasteType)))
        {
            storedWaste[type] = 0;
        }
    }

    private void Update()
    {
        HandleSelectionInput();
    }

    public int GetAmount(WasteType type)
    {
        return storedWaste[type];
    }

    public bool CanStore(WasteType type)
    {
        return storedWaste[type] < capacityPerType;
    }

    public bool TryStore(WasteType type)
    {
        if (!CanStore(type)) return false;

        storedWaste[type]++;
        OnWasteChanged?.Invoke(type, storedWaste[type]);
        return true;
    }

    public bool TryTake(WasteType type)
    {
        if (storedWaste[type] <= 0) return false;

        storedWaste[type]--;
        OnWasteChanged?.Invoke(type, storedWaste[type]);
        return true;
    }

    private void HandleSelectionInput()
    {
        // Direct selection with the number keys 1-5.
        for (int i = 0; i < typeCount && i < 9; i++)
        {
            if (Input.GetKeyDown(KeyCode.Alpha1 + i))
            {
                SetSelected((WasteType)i);
            }
        }

        // Alternative inputs: mouse wheel or gamepad bumpers (LB / RB).
        float scroll = Input.mouseScrollDelta.y;
        if (scroll > 0f || Input.GetKeyDown(KeyCode.JoystickButton5))
        {
            CycleSelection(1);
        }
        else if (scroll < 0f || Input.GetKeyDown(KeyCode.JoystickButton4))
        {
            CycleSelection(-1);
        }
    }

    private void CycleSelection(int step)
    {
        int next = ((int)SelectedType + step + typeCount) % typeCount;
        SetSelected((WasteType)next);
    }

    private void SetSelected(WasteType type)
    {
        if (type == SelectedType) return;

        SelectedType = type;
        OnSelectionChanged?.Invoke(SelectedType);
    }
}
